"""Synthetic crater dataset from monte-carlo-sim HDF5 shards."""

import glob
import os
import math
from typing import Callable, Optional

import h5py
import numpy as np
import torch
from PIL import Image
from torchvision.datasets import VisionDataset


class SyntheticCraterDataset(VisionDataset):
    """PyTorch Dataset for synthetic crater images generated by monte-carlo-sim.

    Reads sharded HDF5 files (shard_*.h5) produced by physinv.dataset.export.
    Each sample: (image, log10(age)).

    Parameters
    ----------
    root : str
        Directory containing shard_*.h5 files.
    transform : callable, optional
        Transform applied to PIL image.
    target_transform : callable, optional
        Transform applied to log10(age) float tensor.
    """

    def __init__(
        self,
        root: str,
        transform: Optional[Callable] = None,
        target_transform: Optional[Callable] = None,
    ) -> None:
        super().__init__(root, transform=transform, target_transform=target_transform)

        shard_paths = sorted(glob.glob(os.path.join(root, "shard_*.h5")))
        if not shard_paths:
            raise FileNotFoundError(f"No shard_*.h5 files found in {root}")

        self._index: list[tuple[str, int]] = []
        for path in shard_paths:
            with h5py.File(path, "r") as f:
                n = int(f["images"].shape[0])
            for i in range(n):
                self._index.append((path, i))

    def __len__(self) -> int:
        return len(self._index)

    def __getitem__(self, idx: int) -> tuple[torch.Tensor, torch.Tensor]:
        path, sample_idx = self._index[idx]
        with h5py.File(path, "r") as f:
            image_np = f["images"][sample_idx]   # (H, W) float32, [0, 1]
            age = float(f["ages"][sample_idx])

        # Convert to uint8 PIL image for torchvision compatibility
        image_uint8 = (image_np * 255).clip(0, 255).astype(np.uint8)
        image_pil = Image.fromarray(image_uint8, mode="L")

        if self.transform is not None:
            image_pil = self.transform(image_pil)
        else:
            image_pil = torch.from_numpy(image_np).unsqueeze(0)  # (1, H, W)

        log_age = torch.tensor(math.log10(max(age, 1.0)), dtype=torch.float32)

        if self.target_transform is not None:
            log_age = self.target_transform(log_age)

        return image_pil, log_age
